create table public.weapon_meta_patches (version text primary key, maintenance_started_at timestamptz not null, starts_at timestamptz not null, timing_status text not null);
create table if not exists public.weapon_meta_match_samples (match_id text not null, platform text not null, player_id text not null, played_at timestamptz not null, match_type text not null, weapon_name text not null, weapon_category text not null, active_pick boolean not null, total_damage numeric not null, total_kills integer not null, total_dbnos integer not null, first_sec_hits integer, sustained_hits integer, sustained_burst_count integer);
